"""Decoding and line splitting shared by the three file parsers."""

import datetime
import re

from .errors import ParseError

SKU_RE = re.compile(r"[A-Za-z]{2,4}-[0-9]{3}")
DATE_RE = re.compile(r"[0-9]{4}-[0-9]{2}-[0-9]{2}")
TOKEN_SPLIT = re.compile(r"[ \t]+")


def decode(data):
    """Decode bytes as strict UTF-8 and drop one leading byte order mark."""
    return strip_bom(data.decode("utf-8"))


def strip_bom(text):
    if text.startswith("﻿"):
        return text[1:]
    return text


def significant_lines(text):
    """Yield ``(line_number, line)`` for every line that is not blank or a comment.

    Lines split only at LF (a trailing CR is dropped, so CRLF works); line
    numbers count every physical line, starting at 1.
    """
    for number, line in enumerate(strip_bom(text).split("\n"), 1):
        if line.endswith("\r"):
            line = line[:-1]
        if line.strip() == "":
            continue
        if line.lstrip().startswith("#"):
            continue
        yield number, line


def parse_date(token, line):
    """Parse ``YYYY-MM-DD`` into a ``datetime.date`` or raise ParseError."""
    date = date_or_none(token)
    if date is None:
        if DATE_RE.fullmatch(token):
            raise ParseError(line, "date %s does not exist" % token)
        raise ParseError(line, "date must look like YYYY-MM-DD, got %r" % token)
    return date


def date_or_none(token):
    if not DATE_RE.fullmatch(token):
        return None
    try:
        return datetime.date(int(token[0:4]), int(token[5:7]), int(token[8:10]))
    except ValueError:
        return None
"""Parsing ``catalog.txt``."""

import re
from dataclasses import dataclass
from decimal import Decimal

from .errors import ParseError
from .textio import SKU_RE, significant_lines

PRICE_RE = re.compile(r"[0-9]+(\.[0-9]{1,2})?")
REORDER_RE = re.compile(r"[0-9]+")
TAXES = ("standard", "reduced", "zero")
CENT = Decimal("0.01")


@dataclass(frozen=True)
class Product:
    sku: str
    name: str
    price: Decimal
    reorder: int
    tax: str


def parse_catalog(text):
    """Return a dict of upper-case SKU to :class:`Product`."""
    catalog = {}
    for number, line in significant_lines(text):
        fields = [f.strip() for f in line.split("|")]
        if len(fields) not in (4, 5):
            raise ParseError(
                number, "expected 4 or 5 fields separated by '|', found %d" % len(fields)
            )
        sku, name, price, reorder = fields[:4]
        if not SKU_RE.fullmatch(sku):
            raise ParseError(number, "bad SKU %r (expected like AB-100)" % sku)
        sku = sku.upper()
        if sku in catalog:
            raise ParseError(number, "duplicate SKU %s" % sku)
        if not name:
            raise ParseError(number, "name must not be empty")
        if not PRICE_RE.fullmatch(price):
            if re.fullmatch(r"[0-9]+\.[0-9]+", price):
                raise ParseError(number, "price must have at most two decimal places")
            raise ParseError(number, "bad price %r" % price)
        value = Decimal(price)
        if value < CENT:
            raise ParseError(number, "price must be at least 0.01")
        if not REORDER_RE.fullmatch(reorder):
            raise ParseError(number, "reorder must be a whole number of zero or more")
        tax = "standard"
        if len(fields) == 5:
            tax = fields[4].lower()
            if tax not in TAXES:
                raise ParseError(number, "tax must be standard, reduced or zero")
        catalog[sku] = Product(sku, name, value.quantize(CENT), int(reorder), tax)
    return catalog
"""Parsing ``movements.txt`` and the never-below-zero rule."""

import re
from dataclasses import dataclass, field
from datetime import date as _date

from .errors import ParseError
from .textio import SKU_RE, TOKEN_SPLIT, parse_date, significant_lines

QUANTITY_RE = re.compile(r"[+-]?[0-9]+")


@dataclass(frozen=True)
class Movement:
    date: _date
    sku: str
    quantity: int
    note: str = ""
    line: int = field(default=0, compare=False, repr=False)


def ordered(movements):
    """Movements in the order they count: by date, file order within a day."""
    return sorted(movements, key=lambda m: m.date)


def first_negative(movements):
    """Return ``(movement, balance)`` of the first movement that takes a SKU
    below zero in counting order, or None."""
    balances = {}
    for m in ordered(movements):
        balance = balances.get(m.sku, 0) + m.quantity
        balances[m.sku] = balance
        if balance < 0:
            return m, balance
    return None


def parse_movements(text, catalog):
    """Return the movements of ``text`` in file order."""
    result = []
    for number, line in significant_lines(text):
        tokens = TOKEN_SPLIT.split(line.strip(), 3)
        if len(tokens) < 3:
            raise ParseError(number, "expected DATE SKU QUANTITY [NOTE]")
        date = parse_date(tokens[0], number)
        sku = tokens[1]
        if not SKU_RE.fullmatch(sku) or sku.upper() not in catalog:
            raise ParseError(number, "unknown SKU %s" % sku)
        sku = sku.upper()
        if not QUANTITY_RE.fullmatch(tokens[2]):
            raise ParseError(number, "quantity must be a whole number, got %r" % tokens[2])
        quantity = int(tokens[2])
        if quantity == 0:
            raise ParseError(number, "quantity must not be zero")
        note = tokens[3].strip() if len(tokens) == 4 else ""
        result.append(Movement(date, sku, quantity, note, number))
    bad = first_negative(result)
    if bad is not None:
        m, balance = bad
        raise ParseError(m.line, "stock of %s would go below zero (%d)" % (m.sku, balance))
    return result
"""Parsing ``orders.txt``."""

import re
from dataclasses import dataclass
from datetime import date as _date
from typing import List, Tuple

from .errors import ParseError
from .textio import TOKEN_SPLIT, parse_date, significant_lines

ORDER_ID_RE = re.compile(r"[Ss][Oo]-[0-9]+")
PAIR_RE = re.compile(r"([A-Za-z]{2,4}-[0-9]{3})\*([0-9]+)")


@dataclass(frozen=True)
class Order:
    id: str
    date: _date
    customer: str
    lines: List[Tuple[str, int]]


def parse_orders(text, catalog):
    """Return the orders of ``text`` in file order."""
    orders = []
    seen = set()
    for number, line in significant_lines(text):
        tokens = TOKEN_SPLIT.split(line.strip())
        if len(tokens) != 4:
            raise ParseError(number, "expected ORDER DATE CUSTOMER LINES")
        order_id, date_text, customer, lines_text = tokens
        if not ORDER_ID_RE.fullmatch(order_id):
            raise ParseError(number, "bad order number %r (expected like SO-1001)" % order_id)
        order_id = order_id.upper()
        if order_id in seen:
            raise ParseError(number, "duplicate order %s" % order_id)
        seen.add(order_id)
        date = parse_date(date_text, number)
        lines = []
        skus = set()
        for pair in lines_text.split(","):
            match = PAIR_RE.fullmatch(pair)
            if not match:
                raise ParseError(number, "bad order line %r (expected SKU*QUANTITY)" % pair)
            sku = match.group(1).upper()
            if sku not in catalog:
                raise ParseError(number, "unknown SKU %s" % sku)
            if sku in skus:
                raise ParseError(number, "SKU %s appears twice in the order" % sku)
            quantity = int(match.group(2))
            if quantity < 1:
                raise ParseError(number, "quantity must be at least 1")
            skus.add(sku)
            lines.append((sku, quantity))
        orders.append(Order(order_id, date, customer, lines))
    return orders
"""Exact order pricing."""

from dataclasses import dataclass
from decimal import ROUND_HALF_UP, Decimal
from typing import List

CENT = Decimal("0.01")
ZERO = Decimal("0.00")
RATES = {"standard": Decimal("0.20"), "reduced": Decimal("0.05"), "zero": Decimal("0")}


def _round(value):
    return value.quantize(CENT, rounding=ROUND_HALF_UP)


def _negated(value):
    """Negative of a non-negative amount, never -0.00."""
    return -value if value else ZERO


@dataclass(frozen=True)
class QuoteLine:
    sku: str
    quantity: int
    unit: Decimal
    gross: Decimal
    discount: Decimal
    net: Decimal


@dataclass(frozen=True)
class Quote:
    lines: List[QuoteLine]
    subtotal: Decimal
    order_discount: Decimal
    tax: Decimal
    total: Decimal


def _volume_rate(quantity):
    if quantity >= 50:
        return Decimal("0.10")
    if quantity >= 10:
        return Decimal("0.05")
    return Decimal("0")


def _allocate(amount, nets):
    """Share ``amount`` over ``nets`` in proportion, to the penny.

    Floor each share, then give the leftover pennies one each to the largest
    fractional remainders, earlier line first on ties. Works in whole pennies.
    """
    cents = int(amount * 100)
    net_cents = [int(n * 100) for n in nets]
    total = sum(net_cents)
    products = [cents * n for n in net_cents]
    shares = [p // total for p in products]
    remainders = [p % total for p in products]
    leftover = cents - sum(shares)
    by_remainder = sorted(range(len(nets)), key=lambda i: (-remainders[i], i))
    for i in by_remainder[:leftover]:
        shares[i] += 1
    return [Decimal(s).scaleb(-2).quantize(CENT) for s in shares]


def price_order(order, catalog):
    """Price a whole order; returns a :class:`Quote` of 2-dp Decimals."""
    lines = []
    for sku, quantity in order.lines:
        unit = _round(catalog[sku].price)
        gross = _round(unit * quantity)
        discount = _negated(_round(gross * _volume_rate(quantity)))
        lines.append(QuoteLine(sku, quantity, unit, gross, discount, gross + discount))
    subtotal = sum((l.net for l in lines), ZERO)
    order_discount = ZERO
    shares = [ZERO] * len(lines)
    if subtotal >= Decimal("500.00"):
        amount = _round(subtotal * Decimal("0.03"))
        order_discount = _negated(amount)
        shares = _allocate(amount, [l.net for l in lines])
    tax = ZERO
    for line, share in zip(lines, shares):
        rate = RATES[catalog[line.sku].tax]
        tax += _round((line.net - share) * rate)
    total = subtotal + order_discount + tax
    return Quote(lines, subtotal, order_discount, tax, total)
"""Errors raised while reading the data files."""


class ParseError(ValueError):
    """A mistake in one of the data files; ``.line`` is the 1-based line number."""

    def __init__(self, line, message):
        super().__init__("line %d: %s" % (line, message))
        self.line = line
        self.message = message
