        ship = max(0, min(owed, available_on(current, sku, date)))
        if ship > 0:
            m = Movement(date, sku, -ship, order_note(order))
            current.append(m)
            new.append(m)
            shipped[sku] += ship
        rows.append((sku, ship, qty - shipped[sku]))
    return rows, new, status_of(order, shipped)


def shipped_order(order, shipped):
    """The order restricted to shipped quantities, or None when nothing shipped."""
