"""The ``stockroom`` command line."""

import csv
import io
import json
import os
import re
import sys
from decimal import Decimal

from . import fulfilment, shelves
from .catalog import parse_catalog
from .errors import ParseError
from .movements import parse_movements
from .orders import parse_orders
from .pricing import price_order
from .textio import date_or_none, decode

USAGE = (
    "usage: stockroom [--dir DIR] COMMAND ...\n"
    "  stock [--json] | low [--json] | history SKU [--json]\n"
    "  receive DATE SKU QUANTITY [NOTE] | ship DATE SKU QUANTITY [NOTE]\n"
    "  quote ORDER [--json] | fulfil ORDER DATE | invoice ORDER [--json]\n"
    "  report [--format text|csv|json]"
)

# command -> (min positionals, max positionals, files read)
COMMANDS = {
    "stock": (0, 0, ("movements",)),
    "low": (0, 0, ("movements",)),
    "history": (1, 1, ("movements",)),
    "receive": (3, 4, ("movements",)),
    "ship": (3, 4, ("movements",)),
    "quote": (1, 1, ("orders",)),
    "fulfil": (2, 2, ("movements", "orders")),
    "invoice": (1, 1, ("movements", "orders")),
    "report": (0, 0, ("movements", "orders")),
}
RAW_ARGS = ("receive", "ship", "fulfil")  # only --dir is an option
FORMATS = ("text", "csv", "json")


class CliExit(Exception):
    def __init__(self, code, message):
        super().__init__(message)
        self.code = code
        self.message = message


def usage_error(message):
    return CliExit(2, "%s\n%s" % (message, USAGE))


def refused(message):
    return CliExit(1, message)


# ---------------------------------------------------------------- arguments


def parse_args(argv):
    """Return ``(command, positionals, options, directory)`` or raise CliExit(2)."""
    directory = "."
    rest = []
    i = 0
    while i < len(argv):
        arg = argv[i]
        if arg == "--dir":
            if i + 1 >= len(argv):
                raise usage_error("--dir needs a value")
            directory = argv[i + 1]
            i += 2
            continue
        if arg.startswith("--dir="):
            directory = arg[len("--dir="):]
        else:
            rest.append(arg)
        i += 1
    if not rest:
        raise usage_error("no command given")
    command = rest[0]
    if command not in COMMANDS:
        raise usage_error("unknown command %r" % command)
    args = rest[1:]
    options = {}
    positionals = []
    if command in RAW_ARGS:
        positionals = args
    else:
        i = 0
        while i < len(args):
            arg = args[i]
            if not arg.startswith("-"):
                positionals.append(arg)
            elif arg == "--json" and command != "report":
                options["json"] = True
            elif command == "report" and arg == "--format":
                if i + 1 >= len(args):
                    raise usage_error("--format needs a value")
                options["format"] = args[i + 1]
                i += 1
            elif command == "report" and arg.startswith("--format="):
                options["format"] = arg[len("--format="):]
            else:
                raise usage_error("unknown option %r" % arg)
            i += 1
        if options.get("format", "text") not in FORMATS:
            raise usage_error("--format must be text, csv or json")
    low, high, _ = COMMANDS[command]
    if not low <= len(positionals) <= high:
        raise usage_error("wrong number of arguments for %s" % command)
    if command in ("receive", "ship"):
        check_date(positionals[0])
    elif command == "fulfil":
        check_date(positionals[1])
    return command, positionals, options, directory


def check_date(text):
    date = date_or_none(text)
    if date is None:
        raise usage_error("bad date %r (expected a real date as YYYY-MM-DD)" % text)
    return date


# -------------------------------------------------------------------- files


def read_file(directory, name, required):
    filename = name + ".txt"
    path = os.path.join(directory, filename)
    try:
        with open(path, "rb") as handle:
            data = handle.read()
    except FileNotFoundError:
        if required:
            raise CliExit(2, "%s: file not found" % filename)
        return b""
    except OSError as exc:
        raise CliExit(2, "%s: cannot read: %s" % (filename, exc.strerror or exc))
    try:
        decode(data)
    except UnicodeDecodeError:
        raise CliExit(2, "%s: not valid UTF-8" % filename)
    return data


def parsed(filename, func, *args):
    try:
        return func(*args)
    except ParseError as exc:
        raise CliExit(1, "%s: %s" % (filename, exc))


class Data:
    """The files one command needs, read and parsed."""

    def __init__(self, directory, needs):
        if not os.path.isdir(directory):
            raise CliExit(2, "%s: no such directory" % directory)
        self.directory = directory
        raw = {"catalog": read_file(directory, "catalog", True)}
        for name in needs:
            raw[name] = read_file(directory, name, False)
        self.raw = raw
        self.catalog = parsed("catalog.txt", parse_catalog, decode(raw["catalog"]))
        self.movements = []
        self.orders = []
        if "movements" in needs:
            self.movements = parsed(
                "movements.txt", parse_movements, decode(raw["movements"]), self.catalog
            )
        if "orders" in needs:
            self.orders = parsed(
                "orders.txt", parse_orders, decode(raw["orders"]), self.catalog
            )

    def find_order(self, text):
        wanted = text.upper()
        for order in self.orders:
            if order.id == wanted:
                return order
        raise refused("unknown order %s" % text)

    def append(self, new_movements):
        """Append movements to movements.txt in a single write."""
        if not new_movements:
            return
        existing = self.raw["movements"]
        text = "".join(shelves.format_movement(m) + "\n" for m in new_movements)
        if existing and not existing.endswith(b"\n"):
            text = "\n" + text
        path = os.path.join(self.directory, "movements.txt")
        try:
            with open(path, "ab") as handle:
                handle.write(text.encode("utf-8"))
        except OSError as exc:
            raise CliExit(2, "movements.txt: cannot write: %s" % (exc.strerror or exc))


# ------------------------------------------------------------------ output


def money(value):
    if value == 0:
        return "0.00"
    return format(value, "f")


def dump(obj):
    return json.dumps(obj, indent=2, ensure_ascii=False) + "\n"


def lines_out(lines):
    return "".join(line + "\n" for line in lines)


def cmd_stock(data, positionals, options):
    rows = shelves.stock_report(data.catalog, data.movements)
    if options.get("json"):
        return dump(
            [{"sku": r.sku, "name": r.name, "onhand": r.onhand, "status": r.status} for r in rows]
        )
    return lines_out("%s %d %s %s" % (r.sku, r.onhand, r.status, r.name) for r in rows)


def cmd_low(data, positionals, options):
    rows = shelves.low_report(data.catalog, data.movements)
    if options.get("json"):
        return dump(
            [
                {"sku": r.sku, "onhand": r.onhand, "reorder": r.reorder, "buy": r.buy}
                for r in rows
            ]
        )
    return lines_out("%s %d %d %d" % r for r in rows)


def cmd_history(data, positionals, options):
    sku = positionals[0].upper()
    if sku not in data.catalog:
        raise refused("unknown SKU %s" % positionals[0])
    rows = shelves.history(sku, data.movements)
    if options.get("json"):
        return dump(
            [
                {"date": r.date.isoformat(), "delta": r.delta, "balance": r.balance, "note": r.note}
                for r in rows
            ]
        )
    out = []
    for r in rows:
        line = "%s %s %d" % (r.date.isoformat(), r.delta, r.balance)
        if r.note:
            line += " " + r.note
        out.append(line)
    return lines_out(out)


def cmd_move(sign):
    def run(data, positionals, options):
        date = check_date(positionals[0])
        quantity_text = positionals[2]
        note = positionals[3] if len(positionals) == 4 else ""
        sku = positionals[1].upper()
        if sku not in data.catalog:
            raise refused("unknown SKU %s" % positionals[1])
        if not re.fullmatch(r"[0-9]+", quantity_text) or int(quantity_text) < 1:
            raise refused("quantity must be a whole number of one or more, got %r" % quantity_text)
        try:
            note.encode("utf-8")
        except UnicodeEncodeError:
            raise refused("note is not valid UTF-8")
        try:
            movement = shelves.append_candidate(
                data.catalog, data.movements, date, sku, sign * int(quantity_text), note
            )
        except shelves.Refused as exc:
            raise refused(str(exc))
        data.append([movement])
        return shelves.format_movement(movement) + "\n"

    return run


def quote_object(order, quote):
    return {
        "order": order.id,
        "date": order.date.isoformat(),
        "customer": order.customer,
        "lines": [
            {
                "sku": l.sku,
                "quantity": l.quantity,
                "unit": money(l.unit),
                "gross": money(l.gross),
                "discount": money(l.discount),
                "net": money(l.net),
            }
            for l in quote.lines
        ],
        "subtotal": money(quote.subtotal),
        "order_discount": money(quote.order_discount),
        "tax": money(quote.tax),
        "total": money(quote.total),
    }


def quote_text(order, quote, prefix=""):
    out = ["%s%s %s %s" % (prefix, order.id, order.date.isoformat(), order.customer)]
    for l in quote.lines:
        out.append(
            "%s %d %s %s %s %s"
            % (l.sku, l.quantity, money(l.unit), money(l.gross), money(l.discount), money(l.net))
        )
    out.append("subtotal " + money(quote.subtotal))
    out.append("order discount " + money(quote.order_discount))
    out.append("tax " + money(quote.tax))
    out.append("total " + money(quote.total))
    return lines_out(out)


def cmd_quote(data, positionals, options):
    order = data.find_order(positionals[0])
    quote = price_order(order, data.catalog)
    if options.get("json"):
        return dump(quote_object(order, quote))
    return quote_text(order, quote)


def cmd_fulfil(data, positionals, options):
    order = data.find_order(positionals[0])
    date = check_date(positionals[1])
    if date < order.date:
        raise refused("%s is dated %s, cannot ship on %s" % (order.id, order.date, date))
