    quote = price_order(billed, data.catalog)
    if options.get("json"):
        return dump(quote_object(billed, quote))
    return quote_text(billed, quote, "invoice ")


def order_sort_key(order):
    return (order.date, int(order.id[3:]), order.id)


def cmd_report(data, positionals, options):
    rows = []
    for order in sorted(data.orders, key=order_sort_key):
